import csv
import io


def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    raw_csv = raw_csv.lstrip("\ufeff")
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')

    parsed = []
    for row in reader:
        parsed.append([cell for cell in row])

    header_index = next(
        (i for i, row in enumerate(parsed) if any(cell.strip() for cell in row)),
        None,
    )
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = parsed[header_index]
    width = max(1, len(columns))
    if len(columns) > width:
        columns = columns[:width - 1] + [",".join(columns[width - 1:])]

    rows = []
    for row in parsed[header_index + 1:]:
        if len(row) > width:
            row = row[:width - 1] + [",".join(row[width - 1:])]
        elif len(row) < width:
            row = row + [""] * (width - len(row))
        rows.append(row)

    return {"columns": columns, "rows": rows}
